from rich.traceback import Traceback
from rich.console import Console
import sys

def test_exception_notes():
    console = Console(force_terminal=True)
    try:
        try:
            raise ValueError("Original error")
        except ValueError as e:
            e.__notes__ = "Some helpful notes"
            raise e
    except ValueError as e:
        # Use sys.exc_info() to get the required arguments for from_exception
        exc_type, exc_value, tb_obj = sys.exc_info()
        tb = Traceback.from_exception(exc_type, exc_value, tb_obj)
        console.print(tb)

if __name__ == "__main__":
    test_exception_notes()

